package dev.myarch.runtime.theme

import java.io.File

/**
 * Renders a palette into the config files each tool expects.
 *
 * This is what makes a theme switch feel instant across the whole system: one
 * palette becomes an Alacritty colour file, a foot ini, a btop theme, a
 * Quickshell QML singleton and a JSON file the launcher itself reads. Tools
 * that re-read their config on change (foot, Quickshell) pick it up without a
 * restart; the rest apply on next launch.
 */
public object ThemeWriter {

    /** Writes every generated file for [theme] into [rootfs]. */
    public fun apply(theme: OmarchyTheme, rootfs: File): List<File> {
        val written = ArrayList<File>()
        written += write(rootfs, "root/.config/myarch/theme.json", json(theme))
        written += write(rootfs, "root/.config/alacritty/colors.toml", alacritty(theme))
        written += write(rootfs, "root/.config/foot/colors.ini", foot(theme))
        written += write(rootfs, "root/.config/btop/themes/myarch.theme", btop(theme))
        written += write(rootfs, "root/.config/quickshell/myarch/Theme.qml", quickshellTheme(theme))
        written += write(rootfs, "root/.config/mako/config", mako(theme))
        written += write(rootfs, "root/.config/waybar/colors.css", waybarCss(theme))
        written += write(rootfs, "root/.config/myarch/current-theme", theme.id + "\n")
        return written
    }

    private fun write(rootfs: File, relativePath: String, content: String): File {
        val file = File(rootfs, relativePath)
        file.parentFile?.mkdirs()
        file.writeText(content)
        return file
    }

    /** The machine-readable form, read by the launcher and by guest scripts. */
    public fun json(theme: OmarchyTheme): String = buildString {
        appendLine("{")
        appendLine("""  "id": "${theme.id}",""")
        appendLine("""  "name": "${theme.name}",""")
        appendLine("""  "light": ${theme.isLight},""")
        appendLine("""  "wallpaper": ${theme.wallpaper?.let { "\"$it\"" } ?: "null"},""")
        appendLine("""  "colors": {""")
        appendLine("""    "background": "${theme.palette.background}",""")
        appendLine("""    "surface": "${theme.palette.surface}",""")
        appendLine("""    "foreground": "${theme.palette.foreground}",""")
        appendLine("""    "muted": "${theme.palette.muted}",""")
        appendLine("""    "accent": "${theme.palette.accent}",""")
        appendLine("""    "accentAlt": "${theme.palette.accentAlt}",""")
        appendLine("""    "warning": "${theme.palette.warning}",""")
        appendLine("""    "error": "${theme.palette.error}",""")
        appendLine("""    "success": "${theme.palette.success}"""")
        appendLine("  },")
        appendLine("""  "ansi": [""")
        appendLine(theme.palette.ansi.joinToString(",\n") { """    "$it"""" })
        appendLine("  ]")
        appendLine("}")
    }

    public fun alacritty(theme: OmarchyTheme): String = buildString {
        appendLine("# Generated by Myarch from the ${theme.name} palette.")
        appendLine("[colors.primary]")
        appendLine("""background = "${theme.palette.background}"""")
        appendLine("""foreground = "${theme.palette.foreground}"""")
        appendLine()
        appendLine("[colors.cursor]")
        appendLine("""text = "${theme.palette.background}"""")
        appendLine("""cursor = "${theme.palette.accent}"""")
        appendLine()
        appendLine("[colors.normal]")
        appendAnsiBlock(theme, offset = 0)
        appendLine()
        appendLine("[colors.bright]")
        appendAnsiBlock(theme, offset = ANSI_BRIGHT_OFFSET)
    }

    private fun StringBuilder.appendAnsiBlock(theme: OmarchyTheme, offset: Int) {
        val names = listOf("black", "red", "green", "yellow", "blue", "magenta", "cyan", "white")
        for ((index, name) in names.withIndex()) {
            appendLine("""$name = "${theme.palette.ansi[offset + index]}"""")
        }
    }

    public fun foot(theme: OmarchyTheme): String = buildString {
        appendLine("# Generated by Myarch from the ${theme.name} palette.")
        appendLine("[colors]")
        appendLine("background=${theme.palette.background.bare()}")
        appendLine("foreground=${theme.palette.foreground.bare()}")
        val names = listOf(
            "regular0", "regular1", "regular2", "regular3",
            "regular4", "regular5", "regular6", "regular7",
            "bright0", "bright1", "bright2", "bright3",
            "bright4", "bright5", "bright6", "bright7",
        )
        for ((index, name) in names.withIndex()) {
            appendLine("$name=${theme.palette.ansi[index].bare()}")
        }
    }

    public fun btop(theme: OmarchyTheme): String = buildString {
        appendLine("# Generated by Myarch from the ${theme.name} palette.")
        appendLine("""theme[main_bg]="${theme.palette.background}"""")
        appendLine("""theme[main_fg]="${theme.palette.foreground}"""")
        appendLine("""theme[title]="${theme.palette.foreground}"""")
        appendLine("""theme[hi_fg]="${theme.palette.accent}"""")
        appendLine("""theme[selected_bg]="${theme.palette.surface}"""")
        appendLine("""theme[selected_fg]="${theme.palette.accent}"""")
        appendLine("""theme[inactive_fg]="${theme.palette.muted}"""")
        appendLine("""theme[graph_text]="${theme.palette.foreground}"""")
        appendLine("""theme[cpu_box]="${theme.palette.surface}"""")
        appendLine("""theme[mem_box]="${theme.palette.surface}"""")
        appendLine("""theme[net_box]="${theme.palette.surface}"""")
        appendLine("""theme[proc_box]="${theme.palette.surface}"""")
        appendLine("""theme[temp_start]="${theme.palette.success}"""")
        appendLine("""theme[temp_mid]="${theme.palette.warning}"""")
        appendLine("""theme[temp_end]="${theme.palette.error}"""")
    }

    /**
     * A QML singleton every Myarch widget imports.
     *
     * Quickshell reloads QML when a file changes, so rewriting this file is all
     * a theme switch needs on the shell side.
     */
    public fun quickshellTheme(theme: OmarchyTheme): String = buildString {
        appendLine("// Generated by Myarch from the ${theme.name} palette. Do not edit by hand:")
        appendLine("// pick a theme in the Myarch app instead.")
        appendLine("pragma Singleton")
        appendLine()
        appendLine("import QtQuick")
        appendLine()
        appendLine("QtObject {")
        appendLine("""    readonly property string name: "${theme.name}"""")
        appendLine("    readonly property bool light: ${theme.isLight}")
        appendLine("""    readonly property color background: "${theme.palette.background}"""")
        appendLine("""    readonly property color surface: "${theme.palette.surface}"""")
        appendLine("""    readonly property color foreground: "${theme.palette.foreground}"""")
        appendLine("""    readonly property color muted: "${theme.palette.muted}"""")
        appendLine("""    readonly property color accent: "${theme.palette.accent}"""")
        appendLine("""    readonly property color accentAlt: "${theme.palette.accentAlt}"""")
        appendLine("""    readonly property color warning: "${theme.palette.warning}"""")
        appendLine("""    readonly property color error: "${theme.palette.error}"""")
        appendLine("""    readonly property color success: "${theme.palette.success}"""")
        appendLine("    readonly property var ansi: [")
        appendLine(theme.palette.ansi.joinToString(",\n") { """        "$it"""" })
        appendLine("    ]")
        appendLine()
        appendLine("    // Shared metrics so widgets line up with each other.")
        appendLine("    readonly property int radius: 14")
        appendLine("    readonly property int gap: 10")
        appendLine("    readonly property int barHeight: 38")
        appendLine("""    readonly property string fontFamily: "JetBrainsMono Nerd Font"""")
        appendLine("    readonly property int fontSize: 13")
        appendLine("}")
    }

    public fun mako(theme: OmarchyTheme): String = buildString {
        appendLine("# Generated by Myarch from the ${theme.name} palette.")
        appendLine("background-color=${theme.palette.surface}")
        appendLine("text-color=${theme.palette.foreground}")
        appendLine("border-color=${theme.palette.accent}")
        appendLine("border-radius=14")
        appendLine("border-size=2")
        appendLine("font=JetBrainsMono Nerd Font 11")
        appendLine("padding=12")
        appendLine("default-timeout=5000")
        appendLine()
        appendLine("[urgency=critical]")
        appendLine("border-color=${theme.palette.error}")
    }

    public fun waybarCss(theme: OmarchyTheme): String = buildString {
        appendLine("/* Generated by Myarch from the ${theme.name} palette. */")
        appendLine("@define-color background ${theme.palette.background};")
        appendLine("@define-color surface ${theme.palette.surface};")
        appendLine("@define-color foreground ${theme.palette.foreground};")
        appendLine("@define-color muted ${theme.palette.muted};")
        appendLine("@define-color accent ${theme.palette.accent};")
        appendLine("@define-color warning ${theme.palette.warning};")
        appendLine("@define-color error ${theme.palette.error};")
    }

    /** foot wants colours without the leading `#`. */
    private fun String.bare(): String = removePrefix("#")

    private const val ANSI_BRIGHT_OFFSET = 8
}
